import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Point> points = new ArrayList<>();
        points.add(new Point(1, 2));
        points.add(new Point(7, 3));
        points.add(new Point(4, 8));
        System.out.println("Before: " + points);

        Point rightmost = points.get(0);
        for (Point p : points) {
            if (p.x > rightmost.x) {
                rightmost = p;
            }
        }
        System.out.println("Rightmost: " + rightmost);

        rightmost.move(0, 7);
        System.out.println("After: " + points);
        System.out.println("Same object: " + (rightmost == points.get(1)));

        Point copy = new Point(rightmost.x, rightmost.y);
        copy.move(1, 1);
        System.out.println("Copy: " + copy + ", list: " + points);
    }
}

class Point {
    int x;
    int y;

    Point(int x, int y) {
        this.x = x;
        this.y = y;
    }

    void move(int dx, int dy) {
        x += dx;
        y += dy;
    }

    @Override
    public String toString() {
        return "(" + x + ", " + y + ")";
    }
}

