import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Item> items = new ArrayList<>();
        items.add(new Item("Lamp", 40));
        items.add(new Item("Desk", 120));
        items.add(new Item("Chair", 75));
        System.out.println("Before: " + items);

        Item priciest = items.get(0);
        for (Item item : items) {
            if (item.price > priciest.price) {
                priciest = item;
            }
        }
        System.out.println("Most expensive: " + priciest);

        priciest.discount(30);
        System.out.println("After: " + items);
        System.out.println("Same object: " + (priciest == items.get(1)));

        Item copy = new Item(priciest.name, priciest.price);
        copy.discount(10);
        System.out.println("Copy: " + copy + ", list: " + items);
    }
}

class Item {
    String name;
    int price;

    Item(String name, int price) {
        this.name = name;
        this.price = price;
    }

    void discount(int amount) {
        price -= amount;
    }

    @Override
    public String toString() {
        return name + " $" + price;
    }
}
